  function updateSystems(dt,time){if(state.level<2)return;updateWaitingQueue();const patiencePaused=state.paused||state.menuOpen||!$("#dialog").hidden||!$("#job-result").hidden||Boolean(state.tutorial),waitRate=state.level===4?.16:.2,activeRate=state.level===4?.09:.05;if(state.waitingCustomer&&!patiencePaused){const w=state.waitingCustomer;w.patience=Math.max(0,w.patience-dt*waitRate);if(w.patience<40&&!w.annoyed){w.annoyed=true;w.customer.worry("I've read this same magazine three times.");}if(w.patience===0&&!w.zeroPenalty){w.zeroPenalty=true;state.reputation=Math.max(0,state.reputation-2);showToast(`${w.scenario.customerName} is annoyed, but will keep waiting.`,"bad");updateHUD();}}state.activeJobs.slice().forEach(job=>{const waitingOnRepair=state.level===4?!job.pendingRecord:!job.fixed;if(waitingOnRepair&&!patiencePaused){job.patience=Math.max(0,job.patience-dt*activeRate);if(job.patience<40&&!job.annoyed){job.annoyed=true;if(job.customer)job.customer.worry("Any progress over there?");}if(job.patience===0&&!job.zeroPenalty){job.zeroPenalty=true;state.reputation=Math.max(0,state.reputation-2);updateHUD();}}if(job.process){job.process.elapsed+=dt*1000;job.status=`${job.process.label}… ${Math.max(0,Math.ceil((job.process.duration-job.process.elapsed)/1000))}s`;if(job.process.elapsed>=job.process.duration){const process=job.process;job.process=null;resolveProcess(job,process);}}});if(state.nextArrivalAt&&time>=state.nextArrivalAt){state.nextArrivalAt=0;spawnCustomer();}const renderKey=[state.selectedJobId,state.waitingCustomer&&`${state.waitingCustomer.customer.state}:${Math.round(state.waitingCustomer.patience)}`,...state.activeJobs.map(job=>`${job.id}:${job.status}:${Math.round(job.patience)}:${job.evidence.length}:${job.hasNewEvidence}`)].join("|");if(renderKey!==state.systemRenderKey){state.systemRenderKey=renderKey;updateNotebook();}}
