  window.addEventListener("keydown",e=>{if(state.running&&state.menuOpen){if(["KeyW","KeyS","ArrowUp","ArrowDown","Enter","KeyE","Space","Escape"].includes(e.code))e.preventDefault();if((e.code==="ArrowUp"||e.code==="KeyW")&&!e.repeat)moveMenuSelection(-1);else if((e.code==="ArrowDown"||e.code==="KeyS")&&!e.repeat)moveMenuSelection(1);else if(["Enter","KeyE","Space"].includes(e.code)&&!e.repeat){const b=menuButtons()[selectedMenuIndex];if(b&&!b.disabled)b.click();}else if(e.code==="Escape"&&!e.repeat)menuBack();return;}if(state.running&&e.code==="Escape"&&!e.repeat&&$("#dialog").hidden&&$("#job-result").hidden){e.preventDefault();openPauseMenu();return;}const move=["KeyW","KeyA","KeyS","KeyD","ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(e.code);if(state.running&&!state.paused&&move){e.preventDefault();keys.add(e.code);}if(state.running&&!state.paused&&(e.code==="KeyE"||e.code==="Space")&&!e.repeat&&!['BUTTON','A'].includes(document.activeElement.tagName)){e.preventDefault();interact();}});window.addEventListener("keyup",e=>keys.delete(e.code));window.addEventListener("blur",()=>keys.clear());
