  $("#close-menu").onclick=menuBack;refreshLevelButtons();saveShopProgress(refreshShopProgress());window.RepairShopRushTest=Object.freeze({state,LEVELS,PROCESS_TIMES,RUSH_PROCESS_TIMES,SHOP_UPGRADES,localDateKey,tipFor,tokenConditions,xpForShift,grantRewards,actionResult,startProcess,testComputer,completeJob,spawnCustomer,acceptWaiting,averagePatience,resetShift,startLevel,startTutorial,noteProgress,toggleTechVision,techVisionCost,techVisionRecommendation,shopProgress,changeShopBalance,purchaseUpgrade,updateSystems,resolveProcess,updateWaitingQueue,selectJob});requestAnimationFrame(loop);
