  function completionButtons(){return [...$("#completion").querySelectorAll("button:not([disabled]), a[href]")].filter(el=>!el.closest("[hidden]"));}
  function selectCompletionAction(index,focus=true){const actions=completionButtons();if(!actions.length)return;const current=actions.indexOf(document.activeElement),next=((index===undefined?current:index)%actions.length+actions.length)%actions.length;actions.forEach((el,i)=>el.classList.toggle("is-selected",i===next));if(focus)actions[next].focus();}
